#!/usr/bin/env node
// OD19 · load — attribute a built chunk's bytes to its source modules.
// usage: node load-chunk-attr.mjs <dist-with-sourcemaps>/assets/<chunk>.js [top=25]
// Counts generated bytes per source by walking the chunk's sourcemap segments.
import { readFileSync } from "node:fs";
import { TraceMap, eachMapping } from "@jridgewell/trace-mapping";

const file = process.argv[2];
const top = Number(process.argv[3] ?? 25);
const code = readFileSync(file, "utf8");
const map = new TraceMap(readFileSync(`${file}.map`, "utf8"));
const lines = code.split("\n");
const segs = [];
eachMapping(map, (m) => segs.push(m));
segs.sort((a, b) => a.generatedLine - b.generatedLine || a.generatedColumn - b.generatedColumn);
const bytes = new Map();
for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    const n = segs[i + 1];
    const end =
        n && n.generatedLine === s.generatedLine
            ? n.generatedColumn
            : lines[s.generatedLine - 1].length;
    const key = (s.source ?? "(none)").replace(/^.*node_modules\//, "nm:").replace(/^.*\/demo\//, "demo/");
    bytes.set(key, (bytes.get(key) ?? 0) + (end - s.generatedColumn));
}
const rows = [...bytes].sort((a, b) => b[1] - a[1]).slice(0, top);
for (const [k, v] of rows) console.log(String(v).padStart(8), k);
console.log(String(code.length).padStart(8), "TOTAL");
